# --- LogQL: stream selector, then line filters, then parsing
{namespace="prod", app="api"} |= "timeout" != "healthcheck"

# parse structured logs at query time and filter on a parsed field
{app="api"} | json | status_code >= 500 | line_format "{{.trace_id}} {{.msg}}"

# turn logs into a metric (useful, not a substitute for real metrics)
sum by (route) (rate({app="api"} | json | status_code >= 500 [5m]))

# --- Elasticsearch: stop dynamic mapping from exploding
PUT _index_template/app-logs
{
  "index_patterns": ["app-logs-*"],
  "template": { "mappings": {
    "dynamic": "strict",
    "properties": {
      "level":   { "type": "keyword" },
      "message": { "type": "text" }
    }
  }}
}

import logging, json
from opentelemetry import trace

class JsonFormatter(logging.Formatter):
    def format(self, record):
        ctx = trace.get_current_span().get_span_context()
        out = {
            "ts": self.formatTime(record),
            "level": record.levelname,
            "service": "checkout-api",
            "msg": record.getMessage(),
        }
        if ctx.is_valid:                    # correlate logs with traces
            out["trace_id"] = format(ctx.trace_id, "032x")
            out["span_id"] = format(ctx.span_id, "016x")
        return json.dumps(out)
